    """Mock LLM for local demonstration without API calls."""

    def invoke(self, messages: Any) -> "MockResponse":
        """Generate a mock response with context-aware content."""
        # Extract the prompt content
        if hasattr(messages, "to_string"):
            prompt_text = messages.to_string()
        elif isinstance(messages, list):
            prompt_text = str(messages[-1].content if messages else "")
        else:
            prompt_text = str(messages)

        # Extract context and question from prompt
        context_start = prompt_text.find("Context:")
        question_start = prompt_text.find("Question:")

        if context_start != -1 and question_start != -1:
            context = prompt_text[context_start:question_start].strip()
            question = prompt_text[question_start:].replace("Question:", "").strip()
        else:
            context = "No context provided"
            question = "No question provided"

        # Generate response based on context
        response = self._generate_answer(context, question)
        return MockResponse(response)

    def _generate_answer(self, context: str, question: str) -> str:
        """Generate answer with citations from context."""
        # Simple mock answer that references the context
        answer_parts = [
            f"Based on the provided context, here's the answer to your question:\n"
        ]

        # Extract key information from context (simple approach)
        lines = [
            line.strip()
            for line in context.split("\n")
            if line.strip() and not line.startswith("Context:")
        ]

        # Create answer with citations
        if lines:
            answer_parts.append(f"\n{question}\n")
            answer_parts.append(
                "\nAccording to the retrieved documents, the relevant information includes:\n"
            )

            # Reference up to 3 context snippets
            for i, line in enumerate(lines[:3], 1):
                if len(line) > 50:  # Only use substantial lines
                    snippet = line[:200] + "..." if len(line) > 200 else line
                    answer_parts.append(f"\n[{i}] {snippet}")

            answer_parts.append(
                "\n\nThis information was retrieved from the document collection and provides context for your query."
            )
        else:
            answer_parts.append(
                "\nI don't have enough information in the context to answer this question."
            )

        return "".join(answer_parts)


